package com.appli.nutristat;

import android.app.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.*;import android.content.*;import java.time.*;import java.util.*;

public class MainActivityV041 extends MainActivity {
 @Override public void onCreate(Bundle b){super.onCreate(b);CatalogExtras.apply(db);loadProfiles(profile==null?0:profile.id);}

 private LinkedHashMap<String,List<NutriDb.Meal>> grouped(String date){LinkedHashMap<String,List<NutriDb.Meal>> out=new LinkedHashMap<>();for(NutriDb.Meal m:db.meals(profile.id,date)){String k=m.time+"|"+m.meal;out.computeIfAbsent(k,x->new ArrayList<>()).add(m);}return out;}
 @Override void today(){String d=LocalDate.now().toString();NutriDb.Nutrients n=db.totals(profile.id,d);content.addView(title("Bilan du jour"));LinearLayout summary=card();TextView kcal=t(Math.round(n.cal)+" / "+Math.round(profile.cal)+" kcal",29,true);kcal.setTextColor(DARK);summary.addView(kcal);progress(summary,"Protéines","g",n.protein,profile.protein,false);progress(summary,"Glucides","g",n.carbs,profile.carbs,false);progress(summary,"Lipides","g",n.fat,profile.fat,false);progress(summary,"Fibres","g",n.fiber,profile.fiber,false);progress(summary,"Sucres","g",n.sugar,profile.sugar,true);content.addView(summary);content.addView(t("Repas enregistrés",19,true));LinkedHashMap<String,List<NutriDb.Meal>> gs=grouped(d);if(gs.isEmpty())content.addView(t("Aucun repas enregistré aujourd'hui.",14,false));for(List<NutriDb.Meal> g:gs.values())mealGroupCard(g);Button q=b("+ Ajouter un repas");q.setOnClickListener(v->mealStep1());content.addView(q,new LinearLayout.LayoutParams(-1,dp(50)));}
 private void mealGroupCard(List<NutriDb.Meal> g){if(g.isEmpty())return;NutriDb.Meal first=g.get(0);LinearLayout c=card();double total=0;for(NutriDb.Meal m:g)total+=m.cal;c.addView(t(first.time+"  ·  "+first.meal+"  ·  "+Math.round(total)+" kcal",16,true));for(NutriDb.Meal m:g){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);TextView info=t("• "+m.item+" · "+(m.amount.isEmpty()?String.format(Locale.FRANCE,"%.1f %s",m.quantity,m.unit):m.amount),13,false);row.addView(info,new LinearLayout.LayoutParams(0,-2,1));Button edit=small("✎",GREEN),del=small("×",RED);edit.setOnClickListener(v->editMeal(m));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Supprimer cet élément ?").setMessage(m.item).setNegativeButton("Annuler",null).setPositiveButton("Supprimer",(d,w)->{db.deleteMeal(m.id);render();}).show());row.addView(edit,new LinearLayout.LayoutParams(dp(48),dp(38)));row.addView(del,new LinearLayout.LayoutParams(dp(48),dp(38)));c.addView(row);}content.addView(c);}
 @Override void showDay(LinearLayout box,String date){box.removeAllViews();NutriDb.Nutrients n=db.totals(profile.id,date);LinearLayout top=card();top.addView(t(date+" · "+Math.round(n.cal)+" kcal",16,true));top.addView(t("P "+Math.round(n.protein)+" g · G "+Math.round(n.carbs)+" g · L "+Math.round(n.fat)+" g · Fibres "+Math.round(n.fiber)+" g",13,false));box.addView(top);for(List<NutriDb.Meal> g:grouped(date).values()){NutriDb.Meal f=g.get(0);LinearLayout c=card();c.addView(t(f.time+" · "+f.meal,14,true));for(NutriDb.Meal m:g)c.addView(t("• "+m.item+" ("+m.amount+")",13,false));box.addView(c);}}

 @Override void catalogBrowser(LinearLayout root,boolean editable){LinearLayout tools=card();tools.addView(t("Type",13,true));Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tous","Aliment","Recette"}));tools.addView(type);tools.addView(t("Catégorie",13,true));Spinner cats=new Spinner(this);cats.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.categories()));tools.addView(cats);EditText search=e("Rechercher par nom ou catégorie…","");tools.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));root.addView(tools);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);root.addView(results);Runnable refresh=()->{List<NutriDb.CatalogItem> items=db.catalog(search.getText().toString(),(String)cats.getSelectedItem(),(String)type.getSelectedItem());results.removeAllViews();if(items.isEmpty())results.addView(t("Aucun résultat.",14,false));for(NutriDb.CatalogItem it:items){LinearLayout c=card();TextView name=t(it.name(),15,true);c.addView(name);LinearLayout details=new LinearLayout(this);details.setOrientation(LinearLayout.VERTICAL);details.setVisibility(View.GONE);details.addView(t(it.isRecipe()?recipeDetail(it.recipe):servingDetail(it.food),13,false));TextView catv=t(it.isRecipe()?"Recettes · "+it.recipe.categories:it.food.categories,12,false);catv.setTextColor(MUTED);details.addView(catv);if(editable){Button ed=small("Éditer",it.isRecipe()?DARK:GREEN);ed.setOnClickListener(v->{if(it.isRecipe())recipeDialog(it.recipe);else foodDialog(it.food);});details.addView(ed,new LinearLayout.LayoutParams(-1,dp(40)));}name.setOnClickListener(v->details.setVisibility(details.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));c.addView(details);results.addView(c);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){refresh.run();}};type.setOnItemSelectedListener(lis);cats.setOnItemSelectedListener(lis);refresh.run();}

 @Override void mealStep2(String date,String time,String mealName){final Dialog dlg=new Dialog(this);LinearLayout outer=new LinearLayout(this);outer.setOrientation(LinearLayout.VERTICAL);outer.setPadding(dp(12),dp(10),dp(12),dp(10));LinearLayout controls=card();controls.addView(t("Type",13,true));Spinner type=new Spinner(this);type.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Tous","Aliment","Recette"}));controls.addView(type);controls.addView(t("Catégorie",13,true));Spinner cats=new Spinner(this);cats.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,db.categories()));controls.addView(cats);EditText search=e("Rechercher…","");controls.addView(search,new LinearLayout.LayoutParams(-1,dp(48)));outer.addView(controls);ScrollView sc=new ScrollView(this);LinearLayout results=new LinearLayout(this);results.setOrientation(LinearLayout.VERTICAL);sc.addView(results);outer.addView(sc,new LinearLayout.LayoutParams(-1,0,1));LinearLayout selectedBox=card();selectedBox.setVisibility(View.GONE);TextView selected=t("",14,true),portion=t("",13,false);selectedBox.addView(selected);selectedBox.addView(portion);EditText qty=labeled(selectedBox,"Quantité consommée","1","");Spinner unit=new Spinner(this);selectedBox.addView(t("Unité",13,true));selectedBox.addView(unit);TextView pending=t("",12,false);selectedBox.addView(pending);outer.addView(selectedBox);final NutriDb.CatalogItem[] chosen={null};ArrayList<Pending> pend=new ArrayList<>();Runnable pendText=()->pending.setText(pend.isEmpty()?"":"Déjà ajoutés : "+pend.size()+" élément(s)");Runnable setUnits=()->{if(chosen[0]==null)return;selectedBox.setVisibility(View.VISIBLE);if(chosen[0].isRecipe()){unit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"portion"}));qty.setText("1");portion.setText(recipeDetail(chosen[0].recipe)+"\nUnité : portion");}else{NutriDb.Food f=chosen[0].food;ArrayList<String> u=new ArrayList<>();if("ml".equals(f.basisUnit)){u.add("cL");u.add("portion");}else{u.add("g");u.add("portion");if("càc".equals(f.defaultUnit))u.add("càc");}unit.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,u));for(int i=0;i<u.size();i++)if(u.get(i).equals(f.defaultUnit))unit.setSelection(i);qty.setText("portion".equals(f.defaultUnit)||"càc".equals(f.defaultUnit)?"1":("cL".equals(f.defaultUnit)?String.valueOf(f.servingBase/10.0):String.valueOf(f.servingBase)));portion.setText(servingDetail(f)+"\nUnité conseillée : "+f.defaultUnit);}};Runnable refresh=()->{results.removeAllViews();for(NutriDb.CatalogItem it:db.catalog(search.getText().toString(),(String)cats.getSelectedItem(),(String)type.getSelectedItem())){LinearLayout c=card();TextView n=t(it.name(),14,true);c.addView(n);c.setOnClickListener(v->{chosen[0]=it;selected.setText(it.name());setUnits.run();});results.addView(c);}};search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});android.widget.AdapterView.OnItemSelectedListener lis=new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?>p){}public void onItemSelected(android.widget.AdapterView<?>p,View v,int i,long id){refresh.run();}};type.setOnItemSelectedListener(lis);cats.setOnItemSelectedListener(lis);LinearLayout buttons=new LinearLayout(this);buttons.setGravity(Gravity.CENTER);Button cancel=small("Annuler",Color.GRAY),add=small("+ Ajouter",ORANGE),save=small("Enregistrer",GREEN);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(52),1);bp.setMargins(dp(3),0,dp(3),0);buttons.addView(cancel,bp);LinearLayout.LayoutParams big=new LinearLayout.LayoutParams(0,dp(58),1.25f);big.setMargins(dp(3),0,dp(3),0);buttons.addView(add,big);buttons.addView(save,bp);outer.addView(buttons);cancel.setOnClickListener(v->dlg.dismiss());Runnable capture=()->{if(chosen[0]==null)return;Pending p=new Pending();p.item=chosen[0];p.qty=num(qty,1);p.unit=(String)unit.getSelectedItem();if(p.item.isRecipe())p.n=new NutriDb.Nutrients(p.item.recipe.cal,p.item.recipe.protein,p.item.recipe.fat,p.item.recipe.carbs,p.item.recipe.fiber,p.item.recipe.sugar).scale(p.qty);else p.n=db.nutrientsFor(p.item.food,p.qty,p.unit);pend.add(p);chosen[0]=null;selectedBox.setVisibility(View.GONE);search.setText("");pendText.run();};add.setOnClickListener(v->capture.run());save.setOnClickListener(v->{if(chosen[0]!=null)capture.run();if(pend.isEmpty()){Toast.makeText(this,"Ajoutez au moins un élément",Toast.LENGTH_SHORT).show();return;}for(Pending p:pend)db.addMeal(profile.id,date,time,mealName,p.item.name(),p.item.isRecipe()?"recipe":"food",p.qty,p.unit,p.n);dlg.dismiss();tab=0;render();});refresh.run();dlg.setContentView(outer);dlg.show();Window w=dlg.getWindow();if(w!=null)w.setLayout(WindowManager.LayoutParams.MATCH_PARENT,WindowManager.LayoutParams.MATCH_PARENT);}

 @Override void weightSection(){content.addView(t("Suivi poids",19,true));LinearLayout advice=card();TextView rec=t("Il est conseillé de se peser une seule fois par semaine, de préférence le même jour et dans les mêmes conditions, pour suivre une tendance globale sans céder au stress des variations quotidiennes.",13,false);rec.setTextColor(MUTED);advice.addView(rec);content.addView(advice);LinearLayout a=card();Button update=b("Mettre à jour mon poids");update.setOnClickListener(v->weightDialog(null));a.addView(update,new LinearLayout.LayoutParams(-1,dp(48)));content.addView(a);List<NutriDb.WeightLog> ws=db.weights(profile.id);if(ws.isEmpty())content.addView(t("Aucune mesure de poids enregistrée.",14,false));else{LinearLayout hist=card();for(int i=ws.size()-1;i>=0;i--){NutriDb.WeightLog w=ws.get(i);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.addView(t(w.date+" · "+String.format(Locale.FRANCE,"%.1f kg",w.weight),14,false),new LinearLayout.LayoutParams(0,-2,1));Button ed=small("Modifier",GREEN);ed.setOnClickListener(v->weightDialog(w));row.addView(ed,new LinearLayout.LayoutParams(dp(92),dp(38)));hist.addView(row);}content.addView(hist);}LinearLayout tabs=new LinearLayout(this);String[] lab={"1 mois","3 mois","6 mois","1 an","Maxi"};int[] months={1,3,6,12,0};LinearLayout chartBox=new LinearLayout(this);chartBox.setOrientation(LinearLayout.VERTICAL);for(int i=0;i<lab.length;i++){final int m=months[i];Button q=small(lab[i],i==0?DARK:GREEN);q.setOnClickListener(v->renderWeightChart(chartBox,m));tabs.addView(q,new LinearLayout.LayoutParams(0,dp(42),1));}content.addView(tabs);content.addView(chartBox);renderWeightChart(chartBox,1);}
}
